     1→/**
     2→ * Road to Nationals API Integration
     3→ * https://www.roadtonationals.com/api
     4→ *
     5→ * Provides access to NCAA gymnastics data including:
     6→ * - Teams and head coaches
     7→ * - Meet schedules
     8→ * - Team rosters
     9→ *
    10→ * Uses Firebase for persistent caching to reduce API calls
    11→ */
    12→
    13→import { db, ref, get, set } from './firebase';
    14→
    15→const RTN_BASE_URL = 'https://www.roadtonationals.com/api';
    16→const CACHE_DURATION = 24 * 60 * 60 * 1000; // 24 hours (data rarely changes)
    17→
    18→/**
    19→ * Fetch all women's teams from Road to Nationals
    20→ * @returns {Promise<{year: string, teams: Array}>}
    21→ */
    22→export async function fetchWomensTeams() {
    23→  const response = await fetch(`${RTN_BASE_URL}/women/teams`);
    24→  if (!response.ok) {
    25→    throw new Error(`Failed to fetch women's teams: ${response.status}`);
    26→  }
    27→  return response.json();
    28→}
    29→
    30→/**
    31→ * Fetch all men's teams from Road to Nationals
    32→ * @returns {Promise<{year: string, teams: Array}>}
    33→ */
    34→export async function fetchMensTeams() {
    35→  const response = await fetch(`${RTN_BASE_URL}/men/teams`);
    36→  if (!response.ok) {
    37→    throw new Error(`Failed to fetch men's teams: ${response.status}`);
    38→  }
    39→  return response.json();
    40→}
    41→
    42→/**
    43→ * Fetch teams for a specific gender
    44→ * @param {'mens' | 'womens'} gender
    45→ * @returns {Promise<{year: string, teams: Array}>}
    46→ */
    47→export async function fetchTeams(gender) {
    48→  return gender === 'womens' ? fetchWomensTeams() : fetchMensTeams();
    49→}
    50→
    51→/**
    52→ * Get head coach for a team
    53→ * @param {string} teamName - Team name (e.g., "California", "Navy", "Stanford")
    54→ * @param {'mens' | 'womens'} gender - Gender of the team
    55→ * @returns {Promise<{firstName: string, lastName: string, fullName: string} | null>}
    56→ */
    57→export async function getHeadCoach(teamName, gender = 'mens') {
    58→  try {
    59→    const data = await fetchTeams(gender);
    60→    const normalizedSearch = normalizeTeamName(teamName);
    61→
    62→    const team = data.teams.find(t => {
    63→      const normalizedName = normalizeTeamName(t.team_name);
    64→      const normalizedFull = normalizeTeamName(t.full_team_name);
    65→      const normalizedShort = normalizeTeamName(t.short_name);
    66→
    67→      return normalizedName === normalizedSearch ||
    68→             normalizedFull.includes(normalizedSearch) ||
    69→             normalizedShort === normalizedSearch ||
    70→             normalizedSearch.includes(normalizedName);
    71→    });
    72→
    73→    if (team && team.hc_first && team.hc_last) {
    74→      return {
    75→        firstName: team.hc_first.trim(),
    76→        lastName: team.hc_last.trim(),
    77→        fullName: `${team.hc_first.trim()} ${team.hc_last.trim()}`,
    78→      };
    79→    }
    80→
    81→    return null;
    82→  } catch (error) {
    83→    console.error('Error fetching head coach:', error);
    84→    return null;
    85→  }
    86→}
    87→
    88→/**
    89→ * Get team info from Road to Nationals
    90→ * @param {string} teamName - Team name
    91→ * @param {'mens' | 'womens'} gender - Gender
    92→ * @returns {Promise<Object | null>}
    93→ */
    94→export async function getTeamInfo(teamName, gender = 'mens') {
    95→  try {
    96→    const data = await fetchTeams(gender);
    97→    const normalizedSearch = normalizeTeamName(teamName);
    98→
    99→    const team = data.teams.find(t => {
   100→      const normalizedName = normalizeTeamName(t.team_name);
   101→      const normalizedFull = normalizeTeamName(t.full_team_name);
   102→      const normalizedShort = normalizeTeamName(t.short_name);
   103→
   104→      return normalizedName === normalizedSearch ||
   105→             normalizedFull.includes(normalizedSearch) ||
   106→             normalizedShort === normalizedSearch ||
   107→             normalizedSearch.includes(normalizedName);
   108→    });
   109→
   110→    if (team) {
   111→      return {
   112→        id: team.id,
   113→        name: team.team_name,
   114→        fullName: team.full_team_name,
   115→        shortName: team.short_name,
   116→        location: team.location,
   117→        headCoach: team.hc_first && team.hc_last
   118→          ? `${team.hc_first.trim()} ${team.hc_last.trim()}`
   119→          : null,
   120→        teamSite: team.team_site,
   121→      };
   122→    }
   123→
   124→    return null;
   125→  } catch (error) {
   126→    console.error('Error fetching team info:', error);
   127→    return null;
   128→  }
   129→}
   130→
   131→/**
   132→ * Get head coaches for multiple teams
   133→ * @param {Array<{name: string, gender: 'mens' | 'womens'}>} teams
   134→ * @returns {Promise<Map<string, {firstName: string, lastName: string, fullName: string}>>}
   135→ */
   136→export async function getHeadCoaches(teams) {
   137→  const results = new Map();
   138→
   139→  // Group by gender to minimize API calls
   140→  const mensTeams = teams.filter(t => t.gender === 'mens');
   141→  const womensTeams = teams.filter(t => t.gender === 'womens');
   142→
   143→  // Fetch data once per gender
   144→  const [mensData, womensData] = await Promise.all([
   145→    mensTeams.length > 0 ? fetchMensTeams() : Promise.resolve({ teams: [] }),
   146→    womensTeams.length > 0 ? fetchWomensTeams() : Promise.resolve({ teams: [] }),
   147→  ]);
   148→
   149→  // Process men's teams
   150→  for (const team of mensTeams) {
   151→    const coach = findCoachInData(team.name, mensData.teams);
   152→    if (coach) {
   153→      results.set(team.name, coach);
   154→    }
   155→  }
   156→
   157→  // Process women's teams
   158→  for (const team of womensTeams) {
   159→    const coach = findCoachInData(team.name, womensData.teams);
   160→    if (coach) {
   161→      results.set(team.name, coach);
   162→    }
   163→  }
   164→
   165→  return results;
   166→}
   167→
   168→/**
   169→ * Find coach in team data array
   170→ * @private
   171→ */
   172→function findCoachInData(teamName, teamsData) {
   173→  const normalizedSearch = normalizeTeamName(teamName);
   174→
   175→  const team = teamsData.find(t => {
   176→    const normalizedName = normalizeTeamName(t.team_name);
   177→    const normalizedFull = normalizeTeamName(t.full_team_name);
   178→    const normalizedShort = normalizeTeamName(t.short_name);
   179→
   180→    return normalizedName === normalizedSearch ||
   181→           normalizedFull.includes(normalizedSearch) ||
   182→           normalizedShort === normalizedSearch ||
   183→           normalizedSearch.includes(normalizedName);
   184→  });
   185→
   186→  if (team && team.hc_first && team.hc_last) {
   187→    return {
   188→      firstName: team.hc_first.trim(),
   189→      lastName: team.hc_last.trim(),
   190→      fullName: `${team.hc_first.trim()} ${team.hc_last.trim()}`,
   191→    };
   192→  }
   193→
   194→  return null;
   195→}
   196→
   197→/**
   198→ * Normalize team name for comparison
   199→ * @private
   200→ */
   201→function normalizeTeamName(name) {
   202→  if (!name) return '';
   203→  return name
   204→    .toLowerCase()
   205→    .replace(/university|college|of|the|state/gi, '')
   206→    .replace(/[^a-z0-9]/g, '')
   207→    .trim();
   208→}
   209→
   210→/**
   211→ * Get weekly schedule for a specific date
   212→ * @param {string} date - Date in YYYY-MM-DD format
   213→ * @param {'mens' | 'womens'} gender
   214→ * @returns {Promise<Object>}
   215→ */
   216→export async function getWeeklySchedule(date, gender = 'womens') {
   217→  const endpoint = gender === 'womens'
   218→    ? `${RTN_BASE_URL}/women/schedule2/${date}/0`
   219→    : `${RTN_BASE_URL}/men/schedulesplit/${date}/0`;
   220→
   221→  const response = await fetch(endpoint);
   222→  if (!response.ok) {
   223→    throw new Error(`Failed to fetch schedule: ${response.status}`);
   224→  }
   225→  return response.json();
   226→}
   227→
   228→/**
   229→ * Get year weeks (dates for each week of the season)
   230→ * @param {number} year
   231→ * @param {'mens' | 'womens'} gender
   232→ * @returns {Promise<Array>}
   233→ */
   234→export async function getYearWeeks(year, gender = 'womens') {
   235→  const genderPath = gender === 'womens' ? 'women' : 'men';
   236→  const response = await fetch(`${RTN_BASE_URL}/${genderPath}/yearweeks/${year}`);
   237→  if (!response.ok) {
   238→    throw new Error(`Failed to fetch year weeks: ${response.status}`);
   239→  }
   240→  return response.json();
   241→}
   242→
   243→// ============================================================================
   244→// Team Dashboard API - Full team data including staff, roster, rankings, etc.
   245→// ============================================================================
   246→
   247→/**
   248→ * Fetch team dashboard data from Road to Nationals (with Firebase caching)
   249→ * Includes: staff, roster, rankings, social links, schedule, team info
   250→ *
   251→ * @param {string} teamId - RTN team ID
   252→ * @param {'mens' | 'womens'} gender
   253→ * @param {number} year - Season year (defaults to current year)
   254→ * @returns {Promise<Object>} Full team dashboard data
   255→ */
   256→export async function fetchTeamDashboard(teamId, gender = 'womens', year = new Date().getFullYear()) {
   257→  const cacheKey = `${gender}-${teamId}`;
   258→  const now = Date.now();
   259→
   260→  // Check in-memory cache first
   261→  if (memoryCache.dashboards[cacheKey]) {
   262→    return memoryCache.dashboards[cacheKey];
   263→  }
   264→
   265→  // Check Firebase cache
   266→  try {
   267→    const cacheRef = ref(db, `rtnCache/dashboards/${cacheKey}`);
   268→    const snapshot = await get(cacheRef);
   269→
   270→    if (snapshot.exists()) {
   271→      const cached = snapshot.val();
   272→      if (cached.timestamp && (now - cached.timestamp) < CACHE_DURATION) {
   273→        memoryCache.dashboards[cacheKey] = cached.data;
   274→        return cached.data;
   275→      }
   276→    }
   277→  } catch {
   278→    // Firebase cache miss
   279→  }
   280→
   281→  // Fetch from API
   282→  const genderPath = gender === 'womens' ? 'women' : 'men';
   283→  const response = await fetch(`${RTN_BASE_URL}/${genderPath}/dashboard/${year}/${teamId}`);
   284→  if (!response.ok) {
   285→    throw new Error(`Failed to fetch team dashboard: ${response.status}`);
   286→  }
   287→  const data = await response.json();
   288→
   289→  // Store in Firebase
   290→  try {
   291→    const cacheRef = ref(db, `rtnCache/dashboards/${cacheKey}`);
   292→    await set(cacheRef, {
   293→      data: data,
   294→      timestamp: now,
   295→      fetchedAt: new Date(now).toISOString(),
   296→    });
   297→  } catch {
   298→    // Firebase write failed
   299→  }
   300→
   301→  // Store in memory
   302→  memoryCache.dashboards[cacheKey] = data;
   303→
   304→  return data;
   305→}
   306→
   307→/**
   308→ * Get team ID from team name using cached teams data
   309→ * @param {string} teamName
   310→ * @param {'mens' | 'womens'} gender
   311→ * @returns {Promise<string | null>}
   312→ */
   313→export async function getTeamId(teamName, gender = 'mens') {
   314→  try {
   315→    const data = await getCachedTeams(gender);
   316→    const normalizedSearch = normalizeTeamName(teamName);
   317→
   318→    const team = data.teams.find(t => {
   319→      const normalizedName = normalizeTeamName(t.team_name);
   320→      const normalizedFull = normalizeTeamName(t.full_team_name);
   321→      const normalizedShort = normalizeTeamName(t.short_name);
   322→
   323→      return normalizedName === normalizedSearch ||
   324→             normalizedFull.includes(normalizedSearch) ||
   325→             normalizedShort === normalizedSearch ||
   326→             normalizedSearch.includes(normalizedName);
   327→    });
   328→
   329→    return team?.id || null;
   330→  } catch {
   331→    return null;
   332→  }
   333→}
   334→
   335→/**
   336→ * Get full team dashboard by team name (convenience function)
   337→ * @param {string} teamName
   338→ * @param {'mens' | 'womens'} gender
   339→ * @param {number} year
   340→ * @returns {Promise<Object | null>}
   341→ */
   342→export async function getTeamDashboard(teamName, gender = 'womens', year = new Date().getFullYear()) {
   343→  const teamId = await getTeamId(teamName, gender);
   344→  if (!teamId) return null;
   345→
   346→  return fetchTeamDashboard(teamId, gender, year);
   347→}
   348→
   349→/**
   350→ * Get coaching staff for a team
   351→ * Returns all coaches including head coach and assistants
   352→ *
   353→ * @param {string} teamName
   354→ * @param {'mens' | 'womens'} gender
   355→ * @returns {Promise<Array<{id: string, firstName: string, lastName: string, fullName: string, position: string, email: string, imageUrl: string}>>}
   356→ */
   357→export async function getCoachingStaff(teamName, gender = 'womens') {
   358→  try {
   359→    const dashboard = await getTeamDashboard(teamName, gender);
   360→    if (!dashboard?.staff) return [];
   361→
   362→    return dashboard.staff
   363→      .filter(s => s.position.toLowerCase().includes('coach'))
   364→      .map(s => ({
   365→        id: s.id,
   366→        firstName: s.first_name?.trim() || '',
   367→        lastName: s.last_name?.trim() || '',
   368→        fullName: `${s.first_name?.trim() || ''} ${s.last_name?.trim() || ''}`.trim(),
   369→        position: s.position,
   370→        email: s.email || '',
   371→        imageUrl: s.image_url ? `https://www.roadtonationals.com/images/staff/${s.image_url}` : null,
   372→      }))
   373→      .sort((a, b) => {
   374→        // Head coach first, then assistants
   375→        if (a.position.toLowerCase().includes('head')) return -1;
   376→        if (b.position.toLowerCase().includes('head')) return 1;
   377→        return 0;
   378→      });
   379→  } catch {
   380→    return [];
   381→  }
   382→}
   383→
   384→/**
   385→ * Get team social media links
   386→ * @param {string} teamName
   387→ * @param {'mens' | 'womens'} gender
   388→ * @returns {Promise<Object>} Links object with facebook, twitter, instagram, etc.
   389→ */
   390→export async function getTeamSocialLinks(teamName, gender = 'womens') {
   391→  try {
   392→    const dashboard = await getTeamDashboard(teamName, gender);
   393→    if (!dashboard?.links) return {};
   394→
   395→    const links = {};
   396→    for (const link of dashboard.links) {
   397→      const type = link.tax_value?.toLowerCase() || '';
   398→      if (type.includes('facebook')) links.facebook = link.link;
   399→      else if (type.includes('twitter')) links.twitter = link.link;
   400→      else if (type.includes('instagram')) links.instagram = link.link;
   401→      else if (type.includes('official')) links.officialSite = link.link;
   402→      else if (type.includes('schedule')) links.schedule = link.link;
   403→      else if (type.includes('roster')) links.roster = link.link;
   404→    }
   405→    return links;
   406→  } catch {
   407→    return {};
   408→  }
   409→}
   410→
   411→/**
   412→ * Get team rankings
   413→ * @param {string} teamName
   414→ * @param {'mens' | 'womens'} gender
   415→ * @returns {Promise<Object | null>} Rankings by event
   416→ */
   417→export async function getTeamRankings(teamName, gender = 'womens') {
   418→  try {
   419→    const dashboard = await getTeamDashboard(teamName, gender);
   420→    if (!dashboard?.ranks) return null;
   421→
   422→    const ranks = dashboard.ranks;
   423→    if (gender === 'womens') {
   424→      return {
   425→        vault: ranks.vault ? parseInt(ranks.vault) : null,
   426→        bars: ranks.bars ? parseInt(ranks.bars) : null,
   427→        beam: ranks.beam ? parseInt(ranks.beam) : null,
   428→        floor: ranks.floor ? parseInt(ranks.floor) : null,
   429→        team: ranks.team ? parseInt(ranks.team) : null,
   430→      };
   431→    } else {
   432→      // Men's events
   433→      return {
   434→        floor: ranks.floor ? parseInt(ranks.floor) : null,
   435→        pommel: ranks.pommel ? parseInt(ranks.pommel) : null,
   436→        rings: ranks.rings ? parseInt(ranks.rings) : null,
   437→        vault: ranks.vault ? parseInt(ranks.vault) : null,
   438→        pBars: ranks.pbars ? parseInt(ranks.pbars) : null,
   439→        hBar: ranks.hbar ? parseInt(ranks.hbar) : null,
   440→        team: ranks.team ? parseInt(ranks.team) : null,
   441→      };
   442→    }
   443→  } catch {
   444→    return null;
   445→  }
   446→}
   447→
   448→/**
   449→ * Get team roster from RTN dashboard
   450→ * @param {string} teamName
   451→ * @param {'mens' | 'womens'} gender
   452→ * @returns {Promise<Array<{id: string, firstName: string, lastName: string, fullName: string, hometown: string, year: number}>>}
   453→ */
   454→export async function getRtnRoster(teamName, gender = 'womens') {
   455→  try {
   456→    const dashboard = await getTeamDashboard(teamName, gender);
   457→    if (!dashboard?.roster) return [];
   458→
   459→    return dashboard.roster.map(r => ({
   460→      id: r.id,
   461→      firstName: r.fname?.trim() || '',
   462→      lastName: r.lname?.trim() || '',
   463→      fullName: `${r.fname?.trim() || ''} ${r.lname?.trim() || ''}`.trim(),
   464→      hometown: r.hometown || '',
   465→      year: r.school_year ? parseInt(r.school_year) : null,
   466→    }));
   467→  } catch {
   468→    return [];
   469→  }
   470→}
   471→
   472→/**
   473→ * Get team schedule/meets from RTN dashboard
   474→ * @param {string} teamName
   475→ * @param {'mens' | 'womens'} gender
   476→ * @returns {Promise<Array>}
   477→ */
   478→export async function getTeamSchedule(teamName, gender = 'womens') {
   479→  try {
   480→    const dashboard = await getTeamDashboard(teamName, gender);
   481→    if (!dashboard?.meets) return [];
   482→
   483→    return dashboard.meets.map(m => ({
   484→      meetId: m.meet_id,
   485→      date: m.meet_date,
   486→      opponent: m.opponent,
   487→      description: m.meet_desc || '',
   488→      home: m.home === 'H',
   489→      away: m.home === 'A',
   490→      score: m.team_score ? parseFloat(m.team_score) : null,
   491→    }));
   492→  } catch {
   493→    return [];
   494→  }
   495→}
   496→
   497→// In-memory cache for current session (backed by Firebase when permissions allow)
   498→// NOTE: Firebase rules must allow read/write to 'rtnCache' path for persistent caching.
   499→// Update your Firebase Realtime Database rules to include:
   500→//   "rtnCache": {
   501→//     ".read": true,
   502→//     ".write": true
   503→//   }
   504→// If Firebase permissions fail, falls back to in-memory caching only.
   505→let memoryCache = {
   506→  mens: null,
   507→  womens: null,
   508→  dashboards: {}, // Cache for team dashboards: { 'womens-66': {...}, 'mens-6': {...} }
   509→};
   510→
   511→/**
   512→ * Get cached team data from Firebase (reduces API calls)
   513→ * @param {'mens' | 'womens'} gender
   514→ * @returns {Promise<{year: string, teams: Array}>}
   515→ */
   516→export async function getCachedTeams(gender) {
   517→  const now = Date.now();
   518→  const cacheKey = gender === 'womens' ? 'womens' : 'mens';
   519→
   520→  // Check in-memory cache first (fastest)
   521→  if (memoryCache[cacheKey]) {
   522→    return memoryCache[cacheKey];
   523→  }
   524→
   525→  // Check Firebase cache
   526→  try {
   527→    const cacheRef = ref(db, `rtnCache/${cacheKey}`);
   528→    const snapshot = await get(cacheRef);
   529→
   530→    if (snapshot.exists()) {
   531→      const cached = snapshot.val();
   532→
   533→      // Check if cache is still valid
   534→      if (cached.timestamp && (now - cached.timestamp) < CACHE_DURATION) {
   535→        // Store in memory for subsequent calls
   536→        memoryCache[cacheKey] = cached.data;
   537→        return cached.data;
   538→      }
   539→    }
   540→  } catch {
   541→    // Firebase cache miss - will fetch from API (permissions may not be set for rtnCache path)
   542→  }
   543→
   544→  // Cache miss or stale - fetch from API
   545→  const data = await fetchTeams(gender);
   546→
   547→  // Store in Firebase
   548→  try {
   549→    const cacheRef = ref(db, `rtnCache/${cacheKey}`);
   550→    await set(cacheRef, {
   551→      data: data,
   552→      timestamp: now,
   553→      fetchedAt: new Date(now).toISOString(),
   554→    });
   555→  } catch {
   556→    // Firebase write failed - data still cached in memory for this session
   557→  }
   558→
   559→  // Store in memory
   560→  memoryCache[cacheKey] = data;
   561→
   562→  return data;
   563→}
   564→
   565→/**
   566→ * Clear the team cache (both Firebase and memory)
   567→ * @param {'mens' | 'womens' | 'all'} gender - Which cache to clear
   568→ */
   569→export async function clearTeamCache(gender = 'all') {
   570→  if (gender === 'all' || gender === 'mens') {
   571→    memoryCache.mens = null;
   572→    try {
   573→      await set(ref(db, 'rtnCache/mens'), null);
   574→    } catch {
   575→      // Firebase clear failed - memory cleared anyway
   576→    }
   577→  }
   578→
   579→  if (gender === 'all' || gender === 'womens') {
   580→    memoryCache.womens = null;
   581→    try {
   582→      await set(ref(db, 'rtnCache/womens'), null);
   583→    } catch {
   584→      // Firebase clear failed - memory cleared anyway
   585→    }
   586→  }
   587→}
   588→
   589→/**
   590→ * Get head coach using cached data (faster for multiple lookups)
   591→ * @param {string} teamName
   592→ * @param {'mens' | 'womens'} gender
   593→ * @returns {Promise<{firstName: string, lastName: string, fullName: string} | null>}
   594→ */
   595→export async function getHeadCoachCached(teamName, gender = 'mens') {
   596→  try {
   597→    const data = await getCachedTeams(gender);
   598→    const coach = findCoachInData(teamName, data.teams);
   599→    return coach;
   600→  } catch (error) {
   601→    console.error('Error fetching head coach:', error);
   602→    return null;
