    84→
    85→  let match;
    86→  while ((match = rowRegex.exec(html)) !== null) {
    87→    const rowHtml = match[1];
    88→
    89→    const imgMatch = rowHtml.match(imgRegex);
    90→    const nameMatch = rowHtml.match(nameRegex);
    91→    const rtnIdMatch = rowHtml.match(rtnIdRegex);
    92→
    93→    if (imgMatch && rtnIdMatch) {
    94→      results.push({
    95→        headshotUrl: imgMatch[1],
    96→        name: nameMatch ? nameMatch[1] : 'Unknown',
    97→        rtnId: rtnIdMatch[1],
    98→      });
    99→    }
   100→  }
   101→
   102→  return results;
   103→}
