   105→/**
   106→ * Fetch RTN dashboard data for all teams in a competition config
   107→ * Returns an object with team1, team2, etc. keys containing RTN data
   108→ * Also merges headshots from Firebase teamsDatabase if available
   109→ */
   110→async function enrichTeamsWithRTN(config, gender = 'womens') {
   111→  const teamData = {};
   112→  const teamNames = [
   113→    config.team1Name,
   114→    config.team2Name,
   115→    config.team3Name,
   116→    config.team4Name,
   117→    config.team5Name,
   118→    config.team6Name,
   119→  ].filter(Boolean); // Remove empty team names
   120→
   121→  // Fetch RTN team dashboards and Firebase headshots in parallel
   122→  const [rtnResults, firebaseHeadshots] = await Promise.all([
   123→    Promise.allSettled(teamNames.map(name => getTeamDashboard(name, gender))),
   124→    getFirebaseHeadshots()
   125→  ]);
   126→
   127→  rtnResults.forEach((result, index) => {
   128→    const teamKey = `team${index + 1}`;
   129→    if (result.status === 'fulfilled' && result.value) {
   130→      const dashboard = result.value;
   131→
   132→      // Extract and normalize the data we care about
   133→      teamData[teamKey] = {
   134→        rtnId: dashboard.id || null,
   135→        fetchedAt: new Date().toISOString(),
   136→
   137→        // Coaching staff (filtered to coaches only)
   138→        coaches: (dashboard.staff || [])
   139→          .filter(s => s.position?.toLowerCase().includes('coach'))
   140→          .map(s => ({
   141→            id: s.id,
   142→            firstName: s.first_name?.trim() || '',
   143→            lastName: s.last_name?.trim() || '',
   144→            fullName: `${s.first_name?.trim() || ''} ${s.last_name?.trim() || ''}`.trim(),
   145→            position: s.position,
   146→            imageUrl: s.image_url ? `https://www.roadtonationals.com/images/staff/${s.image_url}` : null,
   147→          }))
   148→          .sort((a, b) => {
   149→            if (a.position?.toLowerCase().includes('head')) return -1;
   150→            if (b.position?.toLowerCase().includes('head')) return 1;
   151→            return 0;
   152→          }),
   153→
   154→        // Rankings
   155→        rankings: dashboard.ranks ? (gender === 'womens' ? {
   156→          vault: dashboard.ranks.vault ? parseInt(dashboard.ranks.vault) : null,
   157→          bars: dashboard.ranks.bars ? parseInt(dashboard.ranks.bars) : null,
   158→          beam: dashboard.ranks.beam ? parseInt(dashboard.ranks.beam) : null,
   159→          floor: dashboard.ranks.floor ? parseInt(dashboard.ranks.floor) : null,
   160→          team: dashboard.ranks.team ? parseInt(dashboard.ranks.team) : null,
   161→        } : {
   162→          floor: dashboard.ranks.floor ? parseInt(dashboard.ranks.floor) : null,
   163→          pommel: dashboard.ranks.phorse ? parseInt(dashboard.ranks.phorse) : null,
   164→          rings: dashboard.ranks.rings ? parseInt(dashboard.ranks.rings) : null,
   165→          vault: dashboard.ranks.vault ? parseInt(dashboard.ranks.vault) : null,
   166→          pBars: dashboard.ranks.pbars ? parseInt(dashboard.ranks.pbars) : null,
   167→          hBar: dashboard.ranks.highbar ? parseInt(dashboard.ranks.highbar) : null,
   168→          team: dashboard.ranks.team ? parseInt(dashboard.ranks.team) : null,
   169→        }) : null,
   170→
   171→        // Team scoring stats (from RTN 'test' field)
   172→        stats: dashboard.test ? {
   173→          average: dashboard.test.ave || null,
   174→          high: dashboard.test.high || null,
   175→          rqs: dashboard.test.rqs || null, // Ranking Qualifying Score
   176→        } : null,
   177→
   178→        // Roster - merge with Firebase headshots by matching athlete names
   179→        // Uses lookupHeadshot which tries multiple normalized keys for flexible matching
   180→        roster: (dashboard.roster || []).map(r => {
   181→          const firstName = r.fname?.trim() || '';
   182→          const lastName = r.lname?.trim() || '';
   183→          const fullName = `${firstName} ${lastName}`.trim();
   184→          const headshotUrl = lookupHeadshot(firebaseHeadshots, firstName, lastName);
   185→
   186→          return {
   187→            id: r.id,
   188→            firstName,
   189→            lastName,
   190→            fullName,
   191→            hometown: r.hometown || '',
   192→            year: r.school_year ? parseInt(r.school_year) : null,
   193→            headshotUrl, // Merged from Firebase teamsDatabase using flexible matching
   194→          };
   195→        }),
   196→
   197→        // Social links
   198→        links: (() => {
   199→          const links = {};
   200→          for (const link of (dashboard.links || [])) {
   201→            const type = link.tax_value?.toLowerCase() || '';
   202→            if (type.includes('facebook')) links.facebook = link.link;
   203→            else if (type.includes('twitter')) links.twitter = link.link;
   204→            else if (type.includes('instagram')) links.instagram = link.link;
   205→            else if (type.includes('official')) links.officialSite = link.link;
   206→          }
   207→          return links;
   208→        })(),
   209→
   210→        // Schedule
   211→        schedule: (dashboard.meets || []).map(m => ({
   212→          meetId: m.meet_id,
   213→          date: m.meet_date,
   214→          opponent: m.opponent,
   215→          description: m.meet_desc || '',
   216→          home: m.home === 'H',
   217→          away: m.home === 'A',
   218→          score: m.team_score ? parseFloat(m.team_score) : null,
   219→        })),
   220→      };
   221→    }
   222→  });
   223→
   224→  return teamData;
   225→}
