   249→/**
   250→ * Check if we're in a secure (production) context
   251→ * @returns {boolean}
   252→ */
   253→function isSecureContext() {
   254→  return typeof window !== 'undefined' &&
   255→    (window.location.protocol === 'https:' || window.location.hostname === 'commentarygraphic.com');
   256→}
   257→
   258→/**
   259→ * Check VM status by fetching /api/status endpoint
   260→ * In production (HTTPS), routes through the coordinator to avoid Mixed Content errors.
   261→ * In development (HTTP), calls the VM directly.
   262→ *
   263→ * @param {string} vmAddress - The VM address (host:port format, no protocol)
   264→ * @param {number} timeout - Timeout in milliseconds (default 5000)
   265→ * @param {string} compId - Competition ID (required for production routing)
   266→ * @returns {Promise<{online: boolean, obsConnected?: boolean, noVm?: boolean, error?: string}>}
   267→ */
   268→export async function checkVmStatus(vmAddress, timeout = 5000, compId = null) {
   269→  // In production (HTTPS), route through coordinator to avoid Mixed Content
   270→  if (isSecureContext() && compId) {
   271→    const controller = new AbortController();
   272→    const timeoutId = setTimeout(() => controller.abort(), timeout);
   273→
   274→    try {
   275→      const response = await fetch(`https://api.commentarygraphic.com/api/vm/${compId}/status`, {
   276→        signal: controller.signal,
   277→        headers: { 'Accept': 'application/json' },
   278→      });
   279→
   280→      clearTimeout(timeoutId);
   281→
   282→      if (!response.ok) {
   283→        return { online: false, error: `HTTP ${response.status}` };
   284→      }
   285→
   286→      return await response.json();
   287→    } catch (err) {
   288→      clearTimeout(timeoutId);
   289→      if (err.name === 'AbortError') {
   290→        return { online: false, error: 'Request timed out' };
   291→      }
   292→      return { online: false, error: err.message || 'Connection failed' };
   293→    }
   294→  }
   295→
   296→  // Development mode: call VM directly
   297→  if (!isValidVmAddress(vmAddress)) {
   298→    return { online: false, error: 'Invalid VM address format' };
   299→  }
   300→
   301→  const controller = new AbortController();
   302→  const timeoutId = setTimeout(() => controller.abort(), timeout);
   303→
   304→  try {
   305→    const response = await fetch(`http://${vmAddress}/api/status`, {
   306→      signal: controller.signal,
   307→      headers: {
   308→        'Accept': 'application/json',
   309→      },
   310→    });
   311→
   312→    clearTimeout(timeoutId);
   313→
   314→    if (!response.ok) {
   315→      return { online: false, error: `HTTP ${response.status}` };
   316→    }
   317→
   318→    const data = await response.json();
   319→
   320→    return {
   321→      online: true,
   322→      obsConnected: data.obsConnected || false,
   323→    };
   324→  } catch (err) {
   325→    clearTimeout(timeoutId);
   326→
   327→    if (err.name === 'AbortError') {
   328→      return { online: false, error: 'Request timed out' };
   329→    }
   330→
   331→    return { online: false, error: err.message || 'Connection failed' };
   332→  }
   333→}
