   243→  /**
   244→   * Get team logo with flexible matching
   245→   * @param {string} teamName - Team name in any format
   246→   * @param {'womens' | 'mens' | null} preferredGender - Preferred gender for fallback lookup
   247→   */
   248→  const getTeamLogo = useCallback((teamName, preferredGender = null) => {
   249→    if (!teamName) return '';
   250→
   251→    const normalized = normalizeName(teamName);
   252→
   253→    // Direct match
   254→    if (teams[normalized]) return teams[normalized].logo || '';
   255→
   256→    // Try with -mens/-womens suffix removed
   257→    const withoutGender = normalized
   258→      .replace(/-mens$/, '')
   259→      .replace(/-womens$/, '')
   260→      .replace(/ men'?s?$/i, '')
   261→      .replace(/ women'?s?$/i, '');
   262→
   263→    // Determine lookup order based on preferredGender
   264→    const genderOrder = preferredGender === 'womens'
   265→      ? ['womens', 'mens']
   266→      : ['mens', 'womens'];
   267→
   268→    // Check aliases
   269→    const aliasKey = aliases[withoutGender];
   270→    if (aliasKey) {
   271→      for (const gender of genderOrder) {
   272→        const team = teams[`${aliasKey}-${gender}`];
   273→        if (team?.logo) return team.logo;
   274→      }
   275→    }
   276→
   277→    // Try direct school match with gender preference
   278→    for (const gender of genderOrder) {
   279→      if (teams[`${withoutGender}-${gender}`]?.logo) {
   280→        return teams[`${withoutGender}-${gender}`].logo;
   281→      }
   282→    }
   283→
   284→    return '';
   285→  }, [teams, aliases]);
   286→
   287→  /**
   288→   * Get athlete headshot URL using flexible lookup
   289→   * Tries multiple normalized keys to handle accents, hyphens, etc.
   290→   *
   291→   * Lookup order (optimized for speed):
   292→   * 1. Safe Firebase key (most likely match - this is how we save)
   293→   * 2. Normalized name (fallback for legacy data)
   294→   * 3. Extended keys for edge cases (accents, middle names, etc.)
   295→   */
   296→  const getHeadshot = useCallback((athleteName) => {
   297→    if (!athleteName) return '';
   298→
   299→    // Primary lookup: normalize name and convert to safe Firebase key
   300→    // This matches how saveHeadshot() stores the data
   301→    const normalized = normalizeName(athleteName);
   302→    const safeKey = getSafeFirebaseKey(normalized);
   303→
   304→    // Try safe key first (this is how we save headshots)
   305→    if (headshots[safeKey]?.url) {
   306→      return headshots[safeKey].url;
   307→    }
   308→
   309→    // Fallback: try normalized name without safe key transformation
   310→    // (handles legacy data or data imported differently)
   311→    if (headshots[normalized]?.url) {
   312→      return headshots[normalized].url;
   313→    }
   314→
   315→    // Extended fallback: use getLookupKeys for edge cases (accents, middle names, etc.)
   316→    const parts = athleteName.trim().split(/\s+/);
   317→    const firstName = parts[0] || '';
   318→    const lastName = parts.slice(1).join(' ') || '';
   319→    const keys = getLookupKeys(firstName, lastName);
   320→
   321→    for (const key of keys) {
   322→      const keySafe = getSafeFirebaseKey(key);
   323→      if (headshots[keySafe]?.url) {
   324→        return headshots[keySafe].url;
   325→      }
   326→      if (headshots[key]?.url) {
   327→        return headshots[key].url;
   328→      }
   329→    }
   330→
   331→    return '';
   332→  }, [headshots]);
