   368→  /**
   369→   * Resolve a team name to a school key (handles aliases and variations)
   370→   * E.g., "California" -> "cal", "Penn State" -> "penn-state"
   371→   */
   372→  const resolveSchoolKey = useCallback((teamName) => {
   373→    if (!teamName) return null;
   374→
   375→    const normalized = normalizeName(teamName)
   376→      .replace(/ men'?s?$/i, '')
   377→      .replace(/ women'?s?$/i, '')
   378→      .replace(/-mens$/, '')
   379→      .replace(/-womens$/, '');
   380→
   381→    // Check aliases first
   382→    if (aliases[normalized]) {
   383→      return aliases[normalized];
   384→    }
   385→
   386→    // Check if any team key starts with this school name
   387→    const possibleKeys = Object.keys(teams).filter(key =>
   388→      key.startsWith(normalized + '-') ||
   389→      key === normalized
   390→    );
   391→
   392→    if (possibleKeys.length > 0) {
   393→      // Extract school part from key (e.g., "penn-state-mens" -> "penn-state")
   394→      return possibleKeys[0].replace(/-mens$/, '').replace(/-womens$/, '');
   395→    }
   396→
   397→    // Try converting spaces to dashes
   398→    const dashedName = normalized.replace(/ /g, '-');
   399→    if (aliases[dashedName]) {
   400→      return aliases[dashedName];
   401→    }
   402→
   403→    const dashedPossibleKeys = Object.keys(teams).filter(key =>
   404→      key.startsWith(dashedName + '-') ||
   405→      key === dashedName
   406→    );
   407→
   408→    if (dashedPossibleKeys.length > 0) {
   409→      return dashedPossibleKeys[0].replace(/-mens$/, '').replace(/-womens$/, '');
   410→    }
   411→
   412→    return null;
   413→  }, [teams, aliases]);
