   415→  /**
   416→   * Get team with flexible matching (handles various name formats)
   417→   * @param {string} teamName - Team name in any format (e.g., "Penn State", "California Men's")
   418→   * @param {string} gender - Optional gender: 'mens' or 'womens'
   419→   */
   420→  const getTeamFlexible = useCallback((teamName, gender = null) => {
   421→    if (!teamName) return null;
   422→
   423→    // First try exact match
   424→    const exactMatch = getTeam(teamName);
   425→    if (exactMatch) return exactMatch;
   426→
   427→    // Resolve to school key
   428→    const schoolKey = resolveSchoolKey(teamName);
   429→    if (!schoolKey) return null;
   430→
   431→    // Determine gender from input
   432→    const normalized = normalizeName(teamName);
   433→    let targetGender = gender;
   434→    if (!targetGender) {
   435→      if (normalized.includes('women') || normalized.includes('womens')) {
   436→        targetGender = 'womens';
   437→      } else if (normalized.includes('men') || normalized.includes('mens')) {
   438→        targetGender = 'mens';
   439→      }
   440→    }
   441→
   442→    // Try to get team with specific gender
   443→    if (targetGender) {
   444→      const teamWithGender = teams[`${schoolKey}-${targetGender}`];
   445→      if (teamWithGender) return teamWithGender;
   446→    }
   447→
   448→    // Try mens first, then womens
   449→    if (teams[`${schoolKey}-mens`]) return teams[`${schoolKey}-mens`];
   450→    if (teams[`${schoolKey}-womens`]) return teams[`${schoolKey}-womens`];
   451→
   452→    return null;
   453→  }, [teams, getTeam, resolveSchoolKey]);
