   548→  // ============================================
   549→  // DIAGNOSTICS
   550→  // ============================================
   551→
   552→  /**
   553→   * Run data integrity diagnostics
   554→   * Checks for common issues like orphaned headshots, missing data, etc.
   555→   * @returns {Object} Diagnostic results with issues found
   556→   */
   557→  const runDiagnostics = useCallback(() => {
   558→    const issues = [];
   559→    const stats = {
   560→      totalTeams: Object.keys(teams).length,
   561→      totalHeadshots: Object.keys(headshots).length,
   562→      teamsWithRosters: 0,
   563→      teamsWithLogos: 0,
   564→      totalRosterEntries: 0,
   565→      headshotsMatched: 0,
   566→      headshotsOrphaned: 0,
   567→    };
   568→
   569→    // Check each team
   570→    for (const [teamKey, team] of Object.entries(teams)) {
   571→      if (team.logo) stats.teamsWithLogos++;
   572→      if (team.roster?.length > 0) {
   573→        stats.teamsWithRosters++;
   574→        stats.totalRosterEntries += team.roster.length;
   575→
   576→        // Check each roster entry for headshot
   577→        for (const name of team.roster) {
   578→          const headshotUrl = getHeadshot(name);
   579→          if (!headshotUrl) {
   580→            issues.push({
   581→              type: 'missing_headshot',
   582→              severity: 'warning',
   583→              teamKey,
   584→              athleteName: name,
   585→              message: `No headshot found for "${name}" on ${team.displayName || teamKey}`,
   586→            });
   587→          } else {
   588→            stats.headshotsMatched++;
   589→          }
   590→        }
   591→      }
   592→
   593→      // Check for missing required fields
   594→      if (!team.displayName) {
   595→        issues.push({
   596→          type: 'missing_field',
   597→          severity: 'error',
   598→          teamKey,
   599→          field: 'displayName',
   600→          message: `Team "${teamKey}" is missing displayName`,
   601→        });
   602→      }
   603→      if (!team.school) {
   604→        issues.push({
   605→          type: 'missing_field',
   606→          severity: 'error',
   607→          teamKey,
   608→          field: 'school',
   609→          message: `Team "${teamKey}" is missing school name`,
   610→        });
   611→      }
   612→      if (!team.gender) {
   613→        issues.push({
   614→          type: 'missing_field',
   615→          severity: 'error',
   616→          teamKey,
   617→          field: 'gender',
   618→          message: `Team "${teamKey}" is missing gender`,
   619→        });
   620→      }
   621→    }
   622→
   623→    // Check for headshots with invalid teamKey references
   624→    for (const [key, headshot] of Object.entries(headshots)) {
   625→      if (headshot.teamKey && !teams[headshot.teamKey]) {
   626→        issues.push({
   627→          type: 'orphaned_headshot',
   628→          severity: 'warning',
   629→          headshotKey: key,
   630→          athleteName: headshot.name,
   631→          referencedTeam: headshot.teamKey,
   632→          message: `Headshot for "${headshot.name}" references non-existent team "${headshot.teamKey}"`,
   633→        });
   634→        stats.headshotsOrphaned++;
   635→      }
   636→    }
   637→
   638→    // Calculate unmatched headshots (headshots not in any roster)
   639→    const rosterNames = new Set();
   640→    for (const team of Object.values(teams)) {
   641→      if (team.roster) {
   642→        for (const name of team.roster) {
   643→          const normalized = normalizeName(name);
   644→          const safeKey = getSafeFirebaseKey(normalized);
   645→          rosterNames.add(normalized);
   646→          rosterNames.add(safeKey);
   647→        }
   648→      }
   649→    }
   650→
   651→    return {
   652→      stats,
   653→      issues,
   654→      summary: {
   655→        totalIssues: issues.length,
