   591→function RosterView({ teamKey, teams, getTeamRosterWithHeadshots }) {
   592→  const roster = getTeamRosterWithHeadshots(teamKey);
   593→  const team = teams[teamKey];
   594→
   595→  if (!roster || roster.length === 0) {
   596→    return (
   597→      <div className="p-4 border-t border-zinc-700 text-center">
