   617→              )}
   618→            </div>
   619→            <span className="text-xs text-zinc-300 truncate flex-1">{athlete.name}</span>
   620→            {athlete.hasHeadshot ? (
   621→              <CheckCircleIcon className="w-3 h-3 text-green-500 flex-shrink-0" />
   622→            ) : (
   623→              <XCircleIcon className="w-3 h-3 text-red-500 flex-shrink-0" />
   624→            )}
   625→          </div>
   626→        ))}
   627→      </div>
   628→    </div>
   629→  );
   630→}
