   632→function TeamInfoDisplay({ teamName, gender }) {
   633→  const { dashboard, loading } = useTeamDashboard(teamName, gender);
   634→
   635→  if (loading) {
   636→    return (
   637→      <div className="flex items-center justify-center py-8">
   638→        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-cyan-500"></div>
   639→        <span className="ml-3 text-zinc-400">Loading team data from Road to Nationals...</span>
   640→      </div>
   641→    );
   642→  }
   643→
   644→  // Derive all data from the single dashboard response
   645→  const staff = dashboard?.staff
   646→    ?.filter(s => s.position?.toLowerCase().includes('coach'))
   647→    .map(s => ({
   648→      id: s.id,
   649→      fullName: `${s.first_name?.trim() || ''} ${s.last_name?.trim() || ''}`.trim(),
   650→      position: s.position,
   651→      imageUrl: s.image_url ? `https://www.roadtonationals.com/images/staff/${s.image_url}` : null,
   652→    }))
   653→    .sort((a, b) => {
   654→      if (a.position?.toLowerCase().includes('head')) return -1;
   655→      if (b.position?.toLowerCase().includes('head')) return 1;
   656→      return 0;
   657→    }) || [];
   658→
   659→  const links = {};
   660→  if (dashboard?.links) {
   661→    for (const link of dashboard.links) {
   662→      const type = link.tax_value?.toLowerCase() || '';
   663→      if (type.includes('facebook')) links.facebook = link.link;
   664→      else if (type.includes('twitter')) links.twitter = link.link;
   665→      else if (type.includes('instagram')) links.instagram = link.link;
   666→      else if (type.includes('official')) links.officialSite = link.link;
   667→    }
