   672→    vault: ranks.vault ? parseInt(ranks.vault) : null,
   673→    bars: ranks.bars ? parseInt(ranks.bars) : null,
   674→    beam: ranks.beam ? parseInt(ranks.beam) : null,
   675→    floor: ranks.floor ? parseInt(ranks.floor) : null,
   676→    team: ranks.team ? parseInt(ranks.team) : null,
   677→  } : {
   678→    floor: ranks.floor ? parseInt(ranks.floor) : null,
   679→    pommel: ranks.pommel ? parseInt(ranks.pommel) : null,
   680→    rings: ranks.rings ? parseInt(ranks.rings) : null,
   681→    vault: ranks.vault ? parseInt(ranks.vault) : null,
   682→    pBars: ranks.pbars ? parseInt(ranks.pbars) : null,
   683→    hBar: ranks.hbar ? parseInt(ranks.hbar) : null,
   684→    team: ranks.team ? parseInt(ranks.team) : null,
