   709→        <h3 className="text-sm font-semibold text-white mb-3 flex items-center gap-2">
   710→          <UserGroupIcon className="w-4 h-4 text-cyan-500" />
   711→          Coaching Staff ({staff.length})
   712→        </h3>
   713→        {staff.length > 0 ? (
   714→          <div className="space-y-2">
   715→            {staff.map((coach) => (
   716→              <div key={coach.id} className="flex items-center gap-3 p-2 bg-zinc-700/50 rounded">
   717→                <div className="w-10 h-10 bg-zinc-600 rounded-full flex items-center justify-center overflow-hidden flex-shrink-0">
   718→                  {coach.imageUrl ? (
   719→                    <img src={coach.imageUrl} alt={coach.fullName} className="w-10 h-10 object-cover" />
   720→                  ) : (
   721→                    <UserGroupIcon className="w-5 h-5 text-zinc-400" />
   722→                  )}
   723→                </div>
   724→                <div className="flex-1 min-w-0">
   725→                  <div className="text-sm font-medium text-white truncate">{coach.fullName}</div>
   726→                  <div className="text-xs text-zinc-400">{coach.position}</div>
   727→                </div>
   728→              </div>
   729→            ))}
   730→          </div>
   731→        ) : (
