   733→        )}
   734→      </div>
   735→
   736→      {/* Rankings */}
   737→      <div className="bg-zinc-800/50 rounded-lg p-4">
   738→        <h3 className="text-sm font-semibold text-white mb-3 flex items-center gap-2">
   739→          <TrophyIcon className="w-4 h-4 text-yellow-500" />
   740→          National Rankings
   741→        </h3>
   742→        {rankings ? (
   743→          <div className="grid grid-cols-2 gap-2">
   744→            {gender === 'womens' ? (
   745→              <>
   746→                <RankBadge label="Team" rank={rankings.team} />
   747→                <RankBadge label="Vault" rank={rankings.vault} />
   748→                <RankBadge label="Bars" rank={rankings.bars} />
   749→                <RankBadge label="Beam" rank={rankings.beam} />
   750→                <RankBadge label="Floor" rank={rankings.floor} />
   751→              </>
   752→            ) : (
   753→              <>
   754→                <RankBadge label="Team" rank={rankings.team} />
   755→                <RankBadge label="Floor" rank={rankings.floor} />
   756→                <RankBadge label="Pommel" rank={rankings.pommel} />
   757→                <RankBadge label="Rings" rank={rankings.rings} />
   758→                <RankBadge label="Vault" rank={rankings.vault} />
   759→                <RankBadge label="P-Bars" rank={rankings.pBars} />
   760→                <RankBadge label="H-Bar" rank={rankings.hBar} />
   761→              </>
   762→            )}
   763→          </div>
   764→        ) : (
   765→          <p className="text-zinc-500 text-sm">No rankings available</p>
   766→        )}
   767→      </div>
   768→
   769→      {/* Social Links */}
   770→      <div className="bg-zinc-800/50 rounded-lg p-4">
   771→        <h3 className="text-sm font-semibold text-white mb-3 flex items-center gap-2">
   772→          <LinkIcon className="w-4 h-4 text-blue-500" />
   773→          Social & Links
   774→        </h3>
   775→        {Object.keys(links).length > 0 ? (
   776→          <div className="space-y-2">
   777→            {links.officialSite && (
   778→              <SocialLink label="Official Site" url={links.officialSite} />
   779→            )}
   780→            {links.twitter && (
   781→              <SocialLink label="Twitter/X" url={links.twitter} />
   782→            )}
   783→            {links.instagram && (
   784→              <SocialLink label="Instagram" url={links.instagram} />
   785→            )}
   786→            {links.facebook && (
   787→              <SocialLink label="Facebook" url={links.facebook} />
   788→            )}
   789→          </div>
   790→        ) : (
   791→          <p className="text-zinc-500 text-sm">No social links found</p>
   792→        )}
   793→      </div>
   794→
   795→      {/* RTN Roster */}
   796→      <div className="bg-zinc-800/50 rounded-lg p-4">
   797→        <h3 className="text-sm font-semibold text-white mb-3 flex items-center gap-2">
