   449→ * Get team roster from RTN dashboard
   450→ * @param {string} teamName
   451→ * @param {'mens' | 'womens'} gender
   452→ * @returns {Promise<Array<{id: string, firstName: string, lastName: string, fullName: string, hometown: string, year: number}>>}
   453→ */
   454→export async function getRtnRoster(teamName, gender = 'womens') {
   455→  try {
