   457→    if (!dashboard?.roster) return [];
   458→
   459→    return dashboard.roster.map(r => ({
   460→      id: r.id,
   461→      firstName: r.fname?.trim() || '',
   462→      lastName: r.lname?.trim() || '',
   463→      fullName: `${r.fname?.trim() || ''} ${r.lname?.trim() || ''}`.trim(),
   464→      hometown: r.hometown || '',
   465→      year: r.school_year ? parseInt(r.school_year) : null,
   466→    }));
