  UserGroupIcon,
  ChevronDownIcon,
  ChevronRightIcon,
  GlobeAltIcon,
  TrophyIcon,
  LinkIcon,
  ArrowUpTrayIcon,
  CloudArrowUpIcon,
  PlusIcon,
} from '@heroicons/react/24/solid';

export default function MediaManagerPage() {
  const {
    teams,
    loading,
